from collections import deque
def solve(grid):
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; out=[row[:] for row in grid]
    # border flood
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==0 and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    # enclosed regions
    seen2=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==0 and not seen[i][j] and not seen2[i][j]:
                reg=[]; qq=deque([(i,j)]); seen2[i][j]=True
                while qq:
                    a,b=qq.popleft(); reg.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and grid[na][nb]==0 and not seen[na][nb] and not seen2[na][nb]:
                            seen2[na][nb]=True; qq.append((na,nb))
                rs=[a for a,_ in reg]; cs=[b for _,b in reg]
                side=max(max(rs)-min(rs), max(cs)-min(cs))+1
                c=24//side
                for a,b in reg: out[a][b]=c
    return out
